insert into public.units (slug, title, description, position) values ('human-body-systems', 'الوحدة الأولى: أجهزة جسم الإنسان', 'المغذيات والجهاز الهضمي — الصف التاسع، الفصل الأول.', 1)
on conflict (slug) do update set title = excluded.title, description = excluded.description, position = excluded.position;

insert into public.lessons (unit_id, slug, title, summary, position)
select id, 'nutrients', 'المغذيات', 'ما الذي يأخذه جسمك من الطعام؟ تعرّف المغذيات السبعة، ومصادرها، وطرق الكشف عنها، والهرم الغذائي.', 1 from public.units where slug = 'human-body-systems'
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, position = excluded.position;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'intro', 'مقدمة وأهداف الدرس', 1, $j$[{"type":"p","text":"هل تساءلت يوماً عندما شعرت بالجوع وتلهفت لتناول طعامك: ما الذي يأخذه جسمك من الطعام؟ وكيف يتمكن جهازك الهضمي من الاستفادة منه؟ ستجيب عن هذين السؤالين في هذا الدرس."},{"type":"objectives","items":["أصنّف المغذيات الرئيسة وأذكر مصادر كل منها ووظيفته.","أميّز بين السكريات الأحادية والثنائية والمتعددة.","أجري تجارب للكشف عن الكربوهيدرات والبروتينات والدهون وفيتامين C.","أربط نقص بعض الفيتامينات والأملاح المعدنية بالأمراض الناتجة عنه.","أوضّح أهمية الألياف الغذائية والماء للجسم.","أوظّف الهرم الغذائي في إعداد وجبة صحية ومتوازنة."]},{"type":"callout","tone":"info","title":"لماذا يهمّنا هذا الدرس؟","text":"ذكرت وزارة الصحة الفلسطينية في تقريرها السنوي لعام 2015 أن الأمراض المزمنة تحتل المكان الأكبر بين أسباب الوفاة في فلسطين؛ لارتباطها بتغيّر أسلوب الحياة وقلة النشاط البدني والعادات الغذائية السيئة. فللغذاء علاقة مباشرة بالصحة."}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'overview', 'المغذيات والهرم الغذائي', 2, $j$[{"type":"definition","term":"المغذّيات","text":"مواد موجودة في الغذاء يحتاجها الجسم للنمو وللحصول على الطاقة وللمحافظة على صحته. وهي: الكربوهيدرات، والبروتينات، والدهون (الليبيدات)، والفيتامينات، والأملاح المعدنية، والألياف الغذائية، والماء."},{"type":"p","text":"الأطعمة التي نتناولها يومياً تحتوي على مزيج من هذه المغذيات. مثال: إفطار أم محمود (خبز القمح، زيت الزيتون، اللبنة، البندورة، البيض) يضم مغذيات من عدة مجموعات."},{"type":"figure","id":"pyramid","caption":"الهرم الغذائي: القاعدة (الماء والحبوب) تُؤخذ بكمية أكبر، والقمة (الدهون والزيوت والحلويات) بكمية أقل."},{"type":"definition","term":"الهرم الغذائي","text":"ترتيب للمجموعات الغذائية من الأسفل إلى الأعلى حسب أهميتها وحاجة الجسم لها."},{"type":"definition","term":"الغذاء المتوازن","text":"غذاء يحتوي على الأقل على نوع واحد من كل مجموعة غذائية بكميات مناسبة."},{"type":"callout","tone":"tip","title":"لماذا الشكل هرمي؟","text":"رتّب العلماء المجموعات بشكل هرمي لأن عرض كل طابق يمثل الكمية التي يحتاجها الجسم منه: الحبوب في القاعدة لأنها أغذية بناء وطاقة نحتاجها بكثرة، والدهون والحلويات في القمة لأن الإكثار منها يسبب السمنة وأمراض القلب."},{"type":"table","caption":"المحتوى الغذائي للبيض والفاصولياء البيضاء (النسبة المئوية — شكل 3 في الكتاب)","headers":["المغذي","البيض","الفاصولياء البيضاء"],"rows":[["البروتين","12.5%","5.2%"],["الكربوهيدرات","صفر","10.59%"],["الدهون","11.1%","0.48%"],["الفيتامينات والأملاح المعدنية","0.07%","0.05%"],["الماء","76.3%","76.2%"],["الألياف الغذائية","صفر","7.5%"]]},{"type":"conceptmap","id":"nutrient-types"},{"type":"exercise","kind":"classify","prompt":"صنّف كل غذاء إلى المغذّي الرئيس فيه:","categories":["كربوهيدرات","بروتينات","دهون"],"items":[{"text":"الخبز","category":0},{"text":"الأرز","category":0},{"text":"التمر","category":0},{"text":"اللحوم","category":1},{"text":"البيض (زلال)","category":1},{"text":"السمك","category":1},{"text":"زيت الزيتون","category":2},{"text":"المكسّرات","category":2},{"text":"الزبدة","category":2}]}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'carbs', 'الكربوهيدرات (السكريات)', 3, $j$[{"type":"p","text":"تُعدّ الكربوهيدرات المصدر الأساسي للطاقة اللازمة للخلايا؛ لأنها تمدّها بطاقة بسرعة، ويتم امتصاص السكريات الأحادية بسرعة في القناة الهضمية. ومن أغنى مصادرها: الخبز والأرز والحبوب والتمر والعسل والفواكه."},{"type":"callout","tone":"info","title":"مصدر الطاقة المفضّل","text":"يُعدّ الغلوكوز مصدر الطاقة المفضّل لخلايا الدماغ، ومصدراً مهماً للطاقة لجميع خلايا الجسم."},{"type":"p","text":"تتكوّن الكربوهيدرات من جزيء سكر أحادي واحد أو أكثر. وتضم ثلاثة أنواع:"},{"type":"table","headers":["النوع","الوحدات المكوِّنة","أمثلة"],"rows":[["سكريات أحادية","جزيء سكر واحد","الغلوكوز (سكر العنب)، الفركتوز (سكر الفاكهة)، الغالاكتوز"],["سكريات ثنائية","اتحاد جزيئين من السكر الأحادي","المالتوز، السكروز، اللاكتوز"],["سكريات متعددة","اتحاد عدد كبير من السكريات الأحادية","النشا، السيليلوز"]]},{"type":"table","caption":"السكريات الثنائية (جدول 1 في الكتاب)","headers":["السكر الثنائي","السكريات الأحادية المكوّنة له"],"rows":[["المالتوز (سكر الشعير)","غلوكوز + غلوكوز"],["السكروز (سكر المائدة)","غلوكوز + فركتوز"],["اللاكتوز (سكر الحليب)","غلوكوز + غالاكتوز"]]},{"type":"p","text":"الغلوكوز هو السكر الأحادي المشترك بين السكريات الثنائية الثلاثة. ويكثر اللاكتوز في الحليب، والفركتوز في الفواكه والعسل."},{"type":"callout","tone":"tip","title":"ملاحظة من الكتاب","text":"تُصنّف ثنائيات التسكّر ضمن «قليلة التسكر» أيضاً. وعندما تتحد أعداد كبيرة من السكريات الأحادية معاً ينتج عديد التسكر كالنشا والسيليلوز."},{"type":"experiment","title":"نشاط (4): الكشف عن السكريات في الغذاء","materials":["سكر غلوكوز","سكروز (سكر المائدة)","نشا","محلول بندكت","عصير ليمون (أو حمض HCl مخفف)","ماء","أنابيب اختبار","حمام ماء ساخن","محلول لوغول"],"steps":["السكريات الأحادية والثنائية: رقّم 4 أنابيب؛ ضع 3 مل ماء في الأول، و3 مل غلوكوز في الثاني، و3 مل سكروز في الثالث والرابع.","أضف 2 مل من محلول بندكت إلى كل أنبوب، وضعها في حمام ماء ساخن مدة دقيقتين.","أضف قطرتين من عصير الليمون إلى أحد أنبوبي السكروز، ثم أعد التسخين.","عديدات التسكر: ضع 3 مل ماء في الأنبوب (1)، و3 مل من محلول النشا (2%) في الأنبوب (2)، وأضف 2 مل من محلول لوغول إلى كل منهما، ثم سخّن."],"observe":"يتكوّن راسب برتقالي/أحمر طوبي مع الغلوكوز (سكر مختزل) ولا يتكوّن مع الماء. السكروز وحده لا يعطي راسباً، لكنه يعطيه بعد إضافة الحمض. محلول لوغول مع النشا يعطي لوناً أزرق داكناً.","conclude":"بندكت (أو فهلنج A وB) يكشف السكريات المختزلة كالغلوكوز، ولوغول (اليود) يكشف النشا. الأنبوب الذي يحوي ماءً فقط هو أنبوب الضبط (للمقارنة)، والحمض يحلّل السكروز إلى غلوكوز وفركتوز فيعطي نتيجة موجبة."},{"type":"exercise","kind":"match","prompt":"طابِق كل سكر ثنائي بالسكريات الأحادية المكوّنة له:","pairs":[["المالتوز","غلوكوز + غلوكوز"],["السكروز","غلوكوز + فركتوز"],["اللاكتوز","غلوكوز + غالاكتوز"]]},{"type":"conceptmap","id":"carbohydrates"}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'proteins', 'البروتينات والأحماض الأمينية', 4, $j$[{"type":"p","text":"تقوم البروتينات بالعديد من الوظائف: تشكيل الأنزيمات، وتشكيل عدة هرمونات كالإنسولين، وتكوين عضلات الجسم وبناء الأنسجة. من مصادرها: اللحوم والدجاج والسمك والبيض والحليب ومشتقاته والبقوليات (العدس، الفاصولياء، الحمص) والمكسّرات."},{"type":"definition","term":"الحمض الأميني","text":"الوحدة البنائية للبروتين. يقارب عدد الحموض الأمينية 20 حمضاً، وعند اتحاد عدة حموض أمينية معاً تتكوّن سلسلة ببتيد، وعند اتحاد عدد كبير منها يتكوّن البروتين."},{"type":"callout","tone":"info","title":"الحموض الأمينية الأساسية","text":"بعض الحموض الأمينية لا تستطيع خلايا الجسم تصنيعها، لذلك لا بد من توافرها في الغذاء. المصادر الحيوانية للبروتين غنية بجميع الحموض الأمينية، لكن المصادر النباتية تفتقر لبعضها؛ لذا يُنصح بالتنويع بين المصدرين."},{"type":"table","headers":["مصادر حيوانية","مصادر نباتية"],"rows":[["اللحوم، الدجاج، السمك، البيض، الحليب والجبن","العدس، الفاصولياء، الحمص، الفول، المكسّرات"],["غنية بجميع الحموض الأمينية","تفتقر لبعض الحموض الأمينية الأساسية"]]},{"type":"experiment","title":"نشاط (5): الكشف عن البروتينات","materials":["زلال بيض","محلول هيدروكسيد الصوديوم المخفف","محلول كبريتات النحاس (II) 5%","أنابيب اختبار","ماء"],"steps":["رقّم أنبوبين؛ ضع 2 مل ماء في الأنبوب (1) و2 مل زلال بيض في الأنبوب (2).","أضف 2 مل من محلول هيدروكسيد الصوديوم المخفف و2 مل من كبريتات النحاس (II) إلى كل أنبوب.","رجّ كل أنبوب جيداً."],"observe":"يظهر اللون البنفسجي في أنبوب زلال البيض، بينما يبقى أنبوب الماء أزرق فاتحاً.","conclude":"زلال البيض يحتوي على بروتين؛ إذ إن ظهور اللون البنفسجي مع هيدروكسيد الصوديوم وكبريتات النحاس هو الكشف (البيوريت) عن وجود البروتين."},{"type":"conceptmap","id":"proteins"},{"type":"exercise","kind":"truefalse","prompt":"صواب أم خطأ؟","statements":[{"text":"الوحدة البنائية للبروتين هي الحمض الأميني.","answer":true,"why":"تتكوّن البروتينات من وحدات بنائية تُسمّى كل منها حمضاً أمينياً."},{"text":"يستطيع الجسم تصنيع جميع الحموض الأمينية بنفسه.","answer":false,"why":"بعض الحموض الأمينية لا تستطيع الخلايا تصنيعها فيجب الحصول عليها من الغذاء."},{"text":"المصادر النباتية للبروتين غنية بجميع الحموض الأمينية.","answer":false,"why":"المصادر الحيوانية هي الغنية بجميعها، أما النباتية فتفتقر لبعضها."}]}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'lipids', 'الليبيدات (الدهون والزيوت)', 5, $j$[{"type":"p","text":"يندرج تحت بند الليبيدات كل من الزيوت والدهون والكوليسترول. تُعدّ الدهون والزيوت مخازن غنية بالطاقة، ولها دور مهم في تشكيل الغشاء الخلوي، وتشكّل عازلاً حرارياً للجلد وعازلاً كهربائياً للخلايا العصبية. مصادرها: زيت الزيتون، المكسّرات، الأفوكادو، الزبدة، صفار البيض، السمك الدهني."},{"type":"definition","term":"الليبيدات","text":"مواد غذائية لا تذوب في الماء، وهي مخازن غنية بالطاقة للجهد العضلي. تتكوّن الدهون والزيوت من حموض دهنية وغليسرول (جلسرول)."},{"type":"p","text":"عندما تسقط قطعة بطاطا مقلية على الورق تترك بقعة شفافة؛ وهذا يدل على وجود الزيت أو الدهن فيها."},{"type":"experiment","title":"نشاط (6): الكشف عن الزيوت والدهون (اختبار استحلاب الإيثانول)","materials":["زيت زيتون (أو أي زيت آخر)","إيثانول","ماء","أنابيب اختبار"],"steps":["رقّم أنبوبي اختبار.","ضع 1 مل ماء في الأنبوب (1)، و1 مل زيت في الأنبوب (2).","أضف 5 مل إيثانول إلى كل أنبوب، ثم رجّهما جيداً."],"observe":"في أنبوب الماء يبقى السائل رائقاً، أما في أنبوب الزيت فيتكوّن مستحلب أبيض عكر.","conclude":"تذوب الدهون والزيوت في الإيثانول ولا تذوب في الماء. عند إضافة الماء يظهر معلّق (مستحلب) أبيض يدل على وجود الدهن؛ ولذلك يُستخدم الإيثانول للكشف عن الزيوت والدهون."},{"type":"callout","tone":"tip","title":"لماذا لا تذوب الدهون في الماء؟","text":"الماء مركّب قطبي، أما الدهون والزيوت والإيثانول فغير قطبية، والقاعدة: «المذيب يذيب شبيهه»."},{"type":"callout","tone":"extra","title":"معلومة إضافية (خارج الكتاب)","text":"تُصنَّف الدهون عادة إلى مشبعة (غالباً صلبة في درجة حرارة الغرفة، كدهن الحيوانات والزبدة) وغير مشبعة (غالباً سائلة، كزيت الزيتون). يُنصح بالإقلال من الدهون المشبعة والإكثار نسبياً من غير المشبعة."},{"type":"exercise","kind":"classify","prompt":"أي المغذيات يذوب في الماء وأيها لا يذوب؟","categories":["يذوب في الماء","لا يذوب في الماء"],"items":[{"text":"السكر (غلوكوز)","category":0},{"text":"الأملاح المعدنية","category":0},{"text":"زيت الزيتون","category":1},{"text":"الدهن الحيواني","category":1}]}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'vitamins-minerals', 'الفيتامينات والأملاح المعدنية', 6, $j$[{"type":"definition","term":"الفيتامينات والأملاح المعدنية","text":"مواد يحتاجها الجسم بكميات قليلة ونقصها يسبب الأمراض، لكنها مواد أساسية وضرورية لتمكين الجسم من الاستفادة من جميع المغذيات بفاعلية."},{"type":"p","text":"يوجد ما لا يقل عن 15 فيتاميناً و17 من الأملاح المعدنية. من مصادرها: الخضار والفواكه الطازجة (فيتامين C وA)، الحليب ومشتقاته (الكالسيوم)، اللحوم الحمراء والبقوليات (الحديد)، والموز (البوتاسيوم)."},{"type":"table","caption":"أهمية بعض الفيتامينات والمعادن ومخاطر نقصها (جدول 2 في الكتاب)","headers":["الفيتامين / الملح","أهميته","من مخاطر نقصه"],"rows":[["فيتامين C","التئام الجروح، المحافظة على صحة الجلد واللثة","نزيف اللثة، النزيف الداخلي"],["فيتامين D","المساعدة في امتصاص الكالسيوم والاستفادة منه","الكساح عند الصغار، ولين العظام عند الكبار"],["الكالسيوم","يدخل في تركيب العظام والأسنان، ضروري لعمل العضلات، ولتخثّر الدم","الكسور"],["الحديد","صناعة خلايا الدم الحمراء (يدخل في تركيب الهيموغلوبين)","الأنيميا (فقر الدم)"]]},{"type":"callout","tone":"extra","title":"معلومة إضافية (من المراجعات المساندة)","text":"فيتامين A: ضروري للإبصار وصحة الجلد، ونقصه يسبب العشى الليلي. الزنك: يساعد في التئام الجروح ودعم المناعة، ونقصه يبطئ التئام الجروح ويضعف المناعة. هاتان المعلومتان ليستا ضمن جدول الكتاب."},{"type":"experiment","title":"نشاط (7): الكشف عن فيتامين C","materials":["محلول الإندوفينول (DCPIP)","عصير برتقال طبيعي","عصير تفاح","قطّارة","أنابيب اختبار"],"steps":["رقّم أنابيب الاختبار وضع 3 مل من الإندوفينول في كل منها.","أضف عصير البرتقال إلى الأنبوب الأول بالقطّارة قطرة قطرة حتى يختفي اللون، واحسب عدد القطرات.","كرّر الخطوة مع عصير التفاح والماء في الأنبوبين الآخرين."],"observe":"يختفي لون الإندوفينول (الأزرق) عند إضافة العصير الغني بفيتامين C. العصير الذي يزيل اللون بعدد قطرات أقل يحتوي كمية أكبر من فيتامين C.","conclude":"يُكشف فيتامين C بزوال لون الإندوفينول. العصير الذي احتاج إلى قطرات أقل هو الأغنى بفيتامين C."},{"type":"conceptmap","id":"vitamins-minerals"},{"type":"exercise","kind":"match","prompt":"طابِق كل مغذٍّ بأحد أعراض نقصه:","pairs":[["فيتامين C","نزيف اللثة"],["فيتامين D","الكساح ولين العظام"],["الحديد","الأنيميا"],["الكالسيوم","الكسور"]]}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'fiber-water', 'الألياف الغذائية والماء', 7, $j$[{"type":"h","text":"الألياف الغذائية"},{"type":"p","text":"هي الأجزاء الغنية بالسيليلوز وقشور الحبوب من غذائك، والتي لا يتم هضمها داخل القناة الهضمية للإنسان. تشكّل نسبة كبيرة من الفضلات الصلبة إذا تضمّنها الغذاء اليومي."},{"type":"p","text":"وهي ضرورية جداً لتمكين عضلات القناة الهضمية من دفع الفضلات بسرعة (الحركة المعوية)، وبالتالي حماية الجسم من مخاطر الإمساك والسرطان. من مصادرها: الخضار والفواكه والحبوب الكاملة (الخبز الأسمر)، والبقوليات."},{"type":"callout","tone":"tip","title":"لماذا نحتاج السيليلوز مع أنه لا يُهضم؟","text":"لأنه يساعد على الهضم ويمكّن القناة الهضمية من إخراج الفضلات، ويمنع الإمساك والسرطان."},{"type":"h","text":"الماء"},{"type":"p","text":"يشكّل الماء نحو 70% من كتلة جسم الإنسان، فهو يتواجد في سيتوبلازم الخلايا وبلازما الدم وغير ذلك."},{"type":"list","items":["وسط ممتاز لنقل المواد داخل الجسم.","يحافظ على الاتزان الحراري للجسم (تنظيم درجة الحرارة).","مذيب للعديد من المواد؛ ما يتيح المجال لحدوث التفاعلات الكيميائية اللازمة داخل الجسم."]},{"type":"callout","tone":"warn","title":"الإماهة (الترطيب) والجفاف","text":"يفقد جسم الإنسان حوالي 1.5 لتر من الماء يومياً (مع البول والعرق والتنفس والبراز)، وبالتالي يجب تعويض ما يتم فقده بشكل مستمر وشرب القدر الكافي. فقدان الماء الكثير (كما في الإسهال لعدة أيام) يؤدي إلى الجفاف وقد يشكّل خطراً على الطفل."},{"type":"exercise","kind":"truefalse","prompt":"صواب أم خطأ؟","statements":[{"text":"الألياف الغذائية تُهضم داخل القناة الهضمية.","answer":false,"why":"السيليلوز لا يُهضم داخل القناة الهضمية للإنسان."},{"text":"يشكّل الماء حوالي 70% من كتلة الجسم.","answer":true,"why":"ويتواجد في سيتوبلازم الخلايا وبلازما الدم."},{"text":"نقص الألياف قد يسبب الإمساك.","answer":true,"why":"الألياف تساعد عضلات القناة الهضمية على دفع الفضلات."}]}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'balanced-diet', 'الغذاء المتوازن ومقارنات غذائية', 8, $j$[{"type":"p","text":"الوجبة الصحية المتوازنة تضم نوعاً واحداً على الأقل من كل مجموعة من مجموعات الهرم الغذائي، وبكميات تتناسب مع حاجة الجسم. وعند اختيار الوجبة تذكّر أن الماء في القاعدة، ثم الحبوب، فالخضار والفواكه، ثم الحليب واللحوم، وفي القمة الدهون والزيوت والحلويات."},{"type":"table","caption":"مقارنة مختصرة بين المغذيات","headers":["المغذي","الوظيفة الرئيسة","مصادر","الكشف عنه"],"rows":[["الكربوهيدرات","مصدر سريع للطاقة","الخبز، الأرز، التمر","بندكت (السكريات المختزلة) / لوغول (النشا)"],["البروتينات","بناء الأنسجة وتكوين الأنزيمات والهرمونات","اللحوم، البيض، البقوليات","هيدروكسيد الصوديوم + كبريتات النحاس (بنفسجي)"],["الدهون","مخزن غني بالطاقة وعزل حراري","الزيوت، المكسرات، الزبدة","الإيثانول (مستحلب أبيض)"],["الفيتامينات","الوقاية من الأمراض بكميات قليلة","الخضار والفواكه","الإندوفينول لفيتامين C"],["الأملاح المعدنية","بناء العظام، الهيموغلوبين، عمل العضلات","الحليب، اللحوم، الموز","—"],["الألياف","تسهيل خروج الفضلات ومنع الإمساك","الخضار، الحبوب الكاملة","—"],["الماء","نقل المواد، تنظيم الحرارة، مذيب","الماء والعصائر والفواكه","—"]]},{"type":"callout","tone":"info","title":"نمط الغذاء في دول البحر المتوسط","text":"اهتمّ العلماء بنمط التغذية في دول حوض البحر الأبيض المتوسط كفلسطين لانخفاض معدلات الإصابة بأمراض القلب والجلطات والسرطان فيها، ومن سمات هذا النمط: استخدام زيت الزيتون مادةً دهنية رئيسة، وتقليل اللحوم (شهرياً)، وتناول البيض والدجاج والسمك أسبوعياً، وتناول الحبوب والفواكه والبقوليات والخضار واللبن يومياً."},{"type":"exercise","kind":"order","prompt":"رتّب مجموعات الهرم الغذائي من القاعدة إلى القمة:","steps":["الماء","مجموعة الحبوب","مجموعة الخضار والفواكه","مجموعة الحليب واللحوم","مجموعة الدهون والزيوت والحلويات"]},{"type":"callout","tone":"tip","title":"قضية للمناقشة","text":"جمانة في الصف التاسع تخشى زيادة وزنها وتمتنع عن تناول شطيرتها. كيف تعرف أن وزنها مناسب؟ وما المصادر الصحيحة للمعلومات؟ (استشر الطبيب أو اختصاصي التغذية، وارجع إلى المصادر العلمية الموثوقة كالمكتبة والمواقع الصحية الرسمية)."},{"type":"sim","id":"food-journey","label":"انتقل إلى محاكاة رحلة الطعام"}]$j$::jsonb from public.lessons where slug = 'nutrients'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lessons (unit_id, slug, title, summary, position)
select id, 'digestive-system', 'الجهاز الهضمي', 'رحلة لقمة الطعام من الفم حتى فتحة الشرج: الهضم الميكانيكي والكيميائي، الأنزيمات، الامتصاص، والخملات المعوية.', 2 from public.units where slug = 'human-body-systems'
on conflict (slug) do update set title = excluded.title, summary = excluded.summary, position = excluded.position;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'intro', 'مقدمة: كيف يستفيد الجسم من الطعام؟', 1, $j$[{"type":"p","text":"بعد أن عرفت المغذيات الممكن توافرها في طعامك، كيف يتمكن الجسم من استخلاصها من الطعام ليستفيد منها؟ هل تتوقع أن تجد قطعاً من الخبز مثلاً تسري مع تيار الدم؟ بالطبع لا؛ فالطعام يجب أن يُهضم أولاً إلى جزيئات صغيرة قابلة للامتصاص."},{"type":"objectives","items":["أتتبّع مسار لقمة الطعام داخل القناة الهضمية.","أميّز بين الهضم الميكانيكي والهضم الكيميائي.","أسمّي أعضاء القناة الهضمية وملحقاتها وأذكر وظيفة كل منها.","أكتب معادلات الهضم الرئيسة وأحدد الأنزيم المسؤول عن كل منها.","أفسّر تلاؤم تركيب الأمعاء الدقيقة (الخملات) مع وظيفة الامتصاص.","أربط بعض المشكلات الصحية (الإسهال، الإمساك، التهاب الزائدة) بالجهاز الهضمي."]},{"type":"definition","term":"الهضم","text":"تحويل جزيئات الطعام المعقّدة التركيب إلى جزيئات بسيطة قابلة للامتصاص."},{"type":"definition","term":"الجهاز الهضمي","text":"يتكوّن من القناة الهضمية وملحقاتها. القناة الهضمية أنبوب طويل (نحو 7 أمتار) يبدأ بالفم وينتهي بفتحة الشرج."},{"type":"figure","id":"digestive","caption":"رسم تخطيطي للقناة الهضمية وملحقاتها (الغدد اللعابية، الكبد، المرارة، البنكرياس)."},{"type":"conceptmap","id":"digestive-organs"}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'overview', 'مراحل الهضم: الميكانيكي والكيميائي', 2, $j$[{"type":"definition","term":"الهضم الميكانيكي","text":"تحطيم الطعام من قطع كبيرة إلى قطع أصغر بفعل الأسنان (وكذلك حركة عضلات المعدة)، دون تغيير في التركيب الكيميائي للغذاء."},{"type":"definition","term":"الهضم الكيميائي","text":"تحطيم المواد الغذائية إلى وحداتها البنائية القابلة للذوبان والامتصاص بمساعدة الأنزيمات."},{"type":"definition","term":"الأنزيمات","text":"مواد كيميائية (بروتينات) تعمل كمقصّات كيميائية؛ تقطّع جزيئات الغذاء الكبيرة إلى جزيئات أصغر حتى تصل إلى وحداتها البنائية."},{"type":"p","text":"بعد الهضم الميكانيكي تتعرض قطع الطعام المحطّمة لهضم كيميائي بفعل الأنزيمات. فعلى غرار هضم البروتينات (الأنزيمات تقطّع السلاسل الطويلة من الحموض الأمينية إلى سلاسل أقصر ثم إلى حموض أمينية)، تعمل الأنزيمات في هضم الكربوهيدرات والدهون."},{"type":"table","headers":["وجه المقارنة","الهضم الميكانيكي","الهضم الكيميائي"],"rows":[["ما يحدث","تقطيع وطحن وخلط","تغيّر في التركيب الكيميائي (تحلّل بالماء)"],["العامل","الأسنان وعضلات المعدة","الأنزيمات"],["مكانه","الفم والمعدة","الفم والمعدة والأمعاء الدقيقة"],["النتيجة","قطع أصغر وسطح تلامس أكبر","وحدات بنائية قابلة للامتصاص"]]},{"type":"callout","tone":"tip","title":"أهمية الهضم الكيميائي بعد الميكانيكي","text":"الهضم الميكانيكي يزيد مساحة سطح الطعام فتصله الأنزيمات بسهولة أكبر، ثم يحوّل الهضم الكيميائي الجزيئات المعقّدة إلى وحدات بنائية صغيرة تعبر جدار القناة الهضمية إلى الدم (الامتصاص)."},{"type":"sim","id":"mech-chem","label":"شاهد محاكاة الهضم الميكانيكي والكيميائي"},{"type":"exercise","kind":"order","prompt":"رتّب مسار الطعام داخل القناة الهضمية:","steps":["الفم","البلعوم","المريء","المعدة","الأمعاء الدقيقة","الأمعاء الغليظة","فتحة الشرج"]},{"type":"conceptmap","id":"food-path"}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'mouth', 'الفم: الأسنان واللسان والغدد اللعابية', 3, $j$[{"type":"p","text":"تبدأ رحلة الطعام من الفم. تقوم الأسنان بالهضم الميكانيكي؛ إذ تقطّع الطعام وتطحنه. ويبلغ عدد الأسنان عند الإنسان البالغ 32 سناً، ومن أنواعها: القواطع والأنياب والضواحك والطواحن. أما اللسان فيمزج الطعام باللعاب ويدفعه نحو البلعوم."},{"type":"p","text":"تفرز الغدد اللعابية (ثلاثة أزواج) اللعاب الذي يرطّب الطعام، ويهضمه جزئياً لاحتوائه على أنزيم الأميليز الذي يحطّم النشا إلى مالتوز."},{"type":"equation","left":"نشا + ماء","enzyme":"أميليز اللعاب","right":"مالتوز"},{"type":"experiment","title":"نشاط (9): الكشف عن عمل أنزيم أميليز اللعاب","materials":["أنابيب اختبار عدد (2)","محلول نشا (2%)","محلول اليود (لوغول)","لعاب","ماء"],"steps":["رقّم الأنبوبين، ثم أضف 2 سم³ من النشا في كل منهما.","أضف 2 سم³ من الماء في الأنبوب الأول (الضابط).","اغسل فمك بالماء، ثم اجمع نحو 3 سم³ من اللعاب، وأضف 2 سم³ منها في الأنبوب الثاني.","اترك الأنبوبين مدة 20 دقيقة، ثم ضع قطرات من اليود في كل منهما."],"observe":"يظهر اللون الأزرق (أو الأزرق الداكن) في الأنبوب الأول الذي يحوي ماءً (النشا ما زال موجوداً)، أما الأنبوب الثاني (اللعاب) فلا يتغيّر لونه إلى الأزرق لأن النشا تحطّم.","conclude":"تحطيم النشا يبدأ في الفم بفعل أنزيم الأميليز في اللعاب. تغيّر اللون يدل على اختفاء النشا."},{"type":"sim","id":"amylase","label":"شاهد محاكاة عمل أنزيم الأميليز"}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'esophagus', 'البلعوم والمريء والحركة الدودية', 4, $j$[{"type":"p","text":"يصل الطعام المهضوم جزئياً إلى البلعوم ثم يُدفع عبر المريء الذي يتميّز جداره بوجود عضلات دائرية ملساء لا إرادية. ينتقل الطعام بفعل انقباضها متجهاً إلى المعدة بحركة تُسمّى الحركة الدودية."},{"type":"definition","term":"الحركة الدودية","text":"حركة انقباض عضلات المريء (والقناة الهضمية) اللاإرادية لدفع الطعام نحو المعدة، فيتقلص جزء ويرتخي ما بعده فتتحرك اللقمة إلى الأمام."},{"type":"callout","tone":"info","title":"تنبيه","text":"تحدث الحركة الدودية أيضاً في المعدة والأمعاء، وتميّز القناة الهضمية كلها؛ ولذلك يمكن للإنسان أن يبلع الطعام حتى لو كان مقلوباً رأساً على عقب."},{"type":"sim","id":"peristalsis","label":"شاهد محاكاة الحركة الدودية"},{"type":"exercise","kind":"truefalse","prompt":"صواب أم خطأ؟","statements":[{"text":"عضلات المريء إرادية.","answer":false,"why":"عضلات المريء ملساء لا إرادية."},{"text":"الحركة الدودية تدفع الطعام نحو المعدة.","answer":true,"why":"بتقلّص العضلات الدائرية بالتتابع."}]}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'stomach', 'المعدة', 5, $j$[{"type":"p","text":"المعدة كيس عضلي يتميّز جداره بوجود 3 طبقات من العضلات الملساء التي تتقلّص باتجاهات مختلفة، لتسبب عصر الطعام ومزجه بالعصارات الهاضمة (الهضم الميكانيكي). ويُخزَّن فيها الطعام مؤقتاً."},{"type":"p","text":"تفرز جدران المعدة العصارة المعدية التي تحوي أنزيم الببسين الذي يعمل في الوسط الحمضي على تحويل البروتينات إلى عديدات ببتيد، كما تفرز حمض الهيدروكلوريك."},{"type":"equation","left":"بروتين + ماء","enzyme":"ببسين","right":"عديدات ببتيد"},{"type":"figure","id":"stomach","caption":"المعدة: العضلتان العاصرتان (الفؤادية والبوابية) وطبقات العضلات الملساء."},{"type":"callout","tone":"info","title":"حمض الهيدروكلوريك","text":"يقتل معظم الجراثيم المتواجدة داخل الغذاء، ويوفّر الوسط الحمضي اللازم لعمل أنزيم الببسين (لا يستطيع الببسين العمل بدون الحمض)."},{"type":"callout","tone":"tip","title":"لماذا لا تتأثر المعدة بالحمض؟","text":"تفرز جدران المعدة طبقة مخاطية تغطي سطحها الداخلي وتحميها من تأثير الحمض والأنزيمات. (هذه الفكرة مدعومة بالمراجعات المساندة، وليست تفصيلاً مكتوباً في صفحة المعدة من الكتاب.)"},{"type":"sim","id":"pepsin","label":"شاهد محاكاة عمل أنزيم البيبسين"},{"type":"exercise","kind":"match","prompt":"طابق المادة بوظيفتها في المعدة:","pairs":[["حمض الهيدروكلوريك","يقتل معظم الجراثيم ويوفّر وسطاً حمضياً"],["الببسين","يحوّل البروتين إلى عديدات ببتيد"],["عضلات المعدة الملساء","تعصر الطعام وتمزجه (هضم ميكانيكي)"]]}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'small-intestine', 'الإثنا عشر والأمعاء الدقيقة: العصارات والأنزيمات', 6, $j$[{"type":"p","text":"يحدث معظم الهضم الكيميائي لطعامك (ويُسمّى هنا الكيموس الحمضي) بعد مغادرته المعدة، وانتقاله على شكل دفعات إلى الإثني عشر (أول 25 سم من الأمعاء الدقيقة) ليمتزج بثلاث عصارات تصب فيه:"},{"type":"h","text":"أ) العصارة الصفراء (الصفراء)"},{"type":"p","text":"تفرزها الخلايا الكبدية في الكبد وتُخزَّن في المرارة (الحويصلة الصفراوية) قبل إفرازها في الأمعاء الدقيقة. تقوم بدور مشابه للصابون: فهي ضرورية لتحويل الدهون والزيوت إلى مستحلب دهني (قطيرات صغيرة)، ما يسهّل هضم الدهون كيميائياً فيما بعد."},{"type":"figure","id":"liver-bile","caption":"إفراز الصفراء والبنكرياس في الإثني عشر عبر قناة لكل منهما."},{"type":"definition","term":"استحلاب الدهون","text":"تحويل كتلة الدهن الكبيرة إلى قطيرات دقيقة بفعل الصفراء (عمل فيزيائي لا أنزيمي)، فتزداد مساحة سطح الدهن وتصلها أنزيمات الليبيز بسهولة."},{"type":"experiment","title":"نشاط (10): محاكاة دور الصفراء في هضم الدهون","materials":["وعاءان مملوءان إلى منتصفهما بالماء","زيت","صابون سائل"],"steps":["أضف قطرات قليلة من الزيت على سطح الماء في كل من الوعاءين، ولاحظ انفصال السائلين.","أضف بضع قطرات من الصابون إلى أحد الوعاءين، ثم حرّك المحتويات."],"observe":"في الوعاء الذي أضيف إليه الصابون يتفتت الزيت إلى قطيرات صغيرة موزعة في الماء، بينما يبقى الزيت في الوعاء الآخر طبقة منفصلة.","conclude":"الصابون يحوّل الزيت إلى قطيرات صغيرة، وكذلك تفعل الصفراء بالدهون في الإثني عشر."},{"type":"sim","id":"bile","label":"شاهد محاكاة استحلاب الدهون بالصفراء"},{"type":"h","text":"ب) عصارة البنكرياس"},{"type":"p","text":"تحتوي على بيكربونات الصوديوم وأنزيمات هاضمة. تعمل بيكربونات الصوديوم على معادلة حموضة الكيموس الحمضي القادم من المعدة، فتوفّر الوسط المناسب لعمل أنزيمات الأمعاء الدقيقة."},{"type":"equation","left":"نشا + ماء","enzyme":"أميليز البنكرياس","right":"مالتوز"},{"type":"equation","left":"عديدات ببتيد + ماء","enzyme":"تربسين","right":"ببتيدات قصيرة"},{"type":"equation","left":"مستحلب دهني + ماء","enzyme":"ليبيز","right":"غليسرول + حموض دهنية","note":"وهنا يستكمل هضم الدهون"},{"type":"h","text":"ج) عصارة الأمعاء الدقيقة"},{"type":"p","text":"تفرز من جدران الأمعاء الدقيقة، وتضم أنزيمات هاضمة تستكمل هضم البروتينات والكربوهيدرات:"},{"type":"equation","left":"ببتيدات قصيرة + ماء","enzyme":"محلّلات ببتيد","right":"حموض أمينية"},{"type":"equation","left":"مالتوز + ماء","enzyme":"مالتيز","right":"غلوكوز + غلوكوز"},{"type":"equation","left":"سكروز + ماء","enzyme":"سكريز","right":"غلوكوز + فركتوز"},{"type":"equation","left":"لاكتوز + ماء","enzyme":"لاكتيز","right":"غلوكوز + غالاكتوز"},{"type":"callout","tone":"tip","title":"لاحظ التشابه","text":"اسم الأنزيم يشبه اسم المادة التي يهضمها: المالتوز ← مالتيز، السكروز ← سكريز، اللاكتوز ← لاكتيز."},{"type":"callout","tone":"warn","title":"نقص اللاكتيز","text":"نقص أنزيم اللاكتيز يسبب لبعض الناس صعوبات في هضم سكر الحليب (اللاكتوز)."},{"type":"sim","id":"carb-digestion","label":"شاهد محاكاة هضم الكربوهيدرات كاملاً"},{"type":"conceptmap","id":"enzymes"},{"type":"exercise","kind":"match","prompt":"طابق الأنزيم بالمادة التي يهضمها:","pairs":[["الأميليز","النشا"],["الببسين","البروتين"],["المالتيز","المالتوز"],["السكريز","السكروز"],["اللاكتيز","اللاكتوز"],["الليبيز","الدهون (المستحلب الدهني)"]]}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'absorption', 'الامتصاص والخملات المعوية', 7, $j$[{"type":"definition","term":"الامتصاص","text":"نقل الوحدات البنائية الناتجة عن الهضم عبر جدار القناة الهضمية إلى الدم لتصل بعد ذلك إلى جميع الخلايا."},{"type":"p","text":"تتم معظم عملية الامتصاص في الأمعاء الدقيقة التي يتراوح طولها حوالي 6 أمتار، وهي مبطّنة بطبقة مخاطية تنثني من الداخل على شكل بروزات إصبعية تُسمّى خملات (Villi). طول الخملة الواحدة حوالي 1 ملم."},{"type":"figure","id":"villus","caption":"تركيب الخملة المعوية: خلايا طلائية، زوائد دقيقة، شبكة شعيرات دموية، وعاء ليمفي، شريان ووريد."},{"type":"table","caption":"التلاؤم بين تركيب الأمعاء الدقيقة ووظيفة الامتصاص","headers":["الخاصية","أهميتها"],"rows":[["طولها نحو 6 أمتار","تزيد زمن مكوث الطعام وفرصة الامتصاص"],["انثناء الجدار وكثرة الخملات","تزيد مساحة السطح الداخلي (200–300 م²)"],["الزوائد الدقيقة على الخلايا الطلائية","تزيد مساحة السطح أكثر فأكثر"],["شبكة شعيرات دموية في كل خملة","تنقل الغلوكوز والحموض الأمينية وبعض الحموض الدهنية والغليسرول"],["وعاء ليمفي (شعيرة ليمفية) في كل خملة","تحمل معظم الحموض الدهنية والغليسرول ثم تُحمل إلى تيار الدم"]]},{"type":"p","text":"يتم امتصاص الغلوكوز والحموض الأمينية وبعض الحموض الدهنية والغليسرول عبر الشعيرات الدموية ثم نقلها إلى الكبد. أما معظم الحموض الدهنية والغليسرول فيتم حملها عبر الشعيرات الليمفية، ثم تُحمل إلى تيار الدم لتصل إلى جميع خلايا الجسم."},{"type":"sim","id":"absorption","label":"شاهد محاكاة امتصاص الغذاء عبر الخملات"},{"type":"sim","id":"food-journey","label":"شاهد رحلة الطعام كاملة"},{"type":"exercise","kind":"classify","prompt":"أين تُنقل نواتج الهضم بعد الامتصاص؟","categories":["الشعيرات الدموية","الشعيرة الليمفية"],"items":[{"text":"الغلوكوز","category":0},{"text":"الحموض الأمينية","category":0},{"text":"معظم الحموض الدهنية والغليسرول","category":1}]}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'liver', 'الكبد وملحقات القناة الهضمية', 8, $j$[{"type":"p","text":"لماذا يصل الدم المحمّل بالمواد الغذائية إلى الكبد أولاً قبل توزيعه على الخلايا؟ لأن الدم القادم من الأمعاء الدقيقة محمّل بمواد مختلفة تبعاً لمكونات غذائك، وقد يحمل معه مواد خطرة. والكبد هو أكبر عضو داخل جسمك، ويزن أكثر من 1 كغم، ويتكوّن من فصّين (الأيمن والأيسر)."},{"type":"list","items":["يُعدّ مخزناً للغذاء؛ فيُخزّن الغلوكوز والنحاس والحديد والبوتاسيوم وفيتامينات A وB وD.","يُعدّ مصنعاً كيميائياً؛ يُنتج العصارة الصفراء، وينتج مواد لازمة لتخثّر الدم.","يقوم بتنقية الدم من السموم التي مصدرها الجراثيم والكحول والعقاقير."]},{"type":"table","caption":"ملحقات القناة الهضمية","headers":["العضو","وظيفته"],"rows":[["الغدد اللعابية","تفرز اللعاب الذي يحوي أميليز يهضم النشا جزئياً"],["الكبد","يفرز الصفراء، يخزّن الغذاء، ينقّي الدم من السموم"],["المرارة (الحويصلة الصفراوية)","تخزّن الصفراء قبل إفرازها في الإثني عشر"],["البنكرياس","يفرز عصارة تحوي بيكربونات الصوديوم وأنزيمات (أميليز، تربسين، ليبيز)"]]},{"type":"callout","tone":"tip","title":"تراث","text":"يقال في التراث: «أطفالنا أكبادنا تمشي على الأرض»."},{"type":"conceptmap","id":"digestive-organs"}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'large-intestine', 'الأمعاء الغليظة والتخلص من الفضلات', 9, $j$[{"type":"p","text":"الأمعاء الغليظة أنبوب عريض على شكل حرف U مقلوب، طوله نحو 1.5 متر. يتكوّن القولون من أجزاء: القولون الصاعد، القولون المستعرض، القولون النازل، ثم المستقيم الذي ينتهي بفتحة الشرج. وتتصل بها الزائدة الدودية عند التقاء الأمعاء الدقيقة بالغليظة (في الجهة اليمنى السفلى من البطن)."},{"type":"p","text":"يتم امتصاص معظم الماء مما تبقّى من الغذاء عندما يصل إلى الأمعاء الغليظة، أما المواد التي لا يمكن هضمها (كالألياف) فتمرّ عبر الأمعاء الغليظة لتخرج من فتحة الشرج على شكل فضلات (براز)."},{"type":"figure","id":"digestive","caption":"رسم القناة الهضمية: لاحظ موقع الأمعاء الغليظة والزائدة الدودية."},{"type":"table","caption":"زمن بقاء الطعام التقريبي في أجزاء القناة الهضمية (من الرسم البياني في أسئلة الدرس — قيم تقريبية)","headers":["العضو","الزمن التقريبي"],"rows":[["الفم والمريء","أقل من ساعة"],["المعدة","نحو 4 ساعات"],["الأمعاء الدقيقة","نحو 7 ساعات"],["الأمعاء الغليظة","نحو 13 ساعة"]]},{"type":"callout","tone":"info","title":"أين يقضي الطعام معظم وقته؟","text":"الطعام يقضي معظم وقته في الأمعاء الغليظة؛ لأن الماء يُمتص فيها ببطء ولتجميع الفضلات. أما مزج الطعام لتكوين الكيموس فيحدث في المعدة، ويمكث فيها نحو 4 ساعات."},{"type":"p","text":"إذا تكرر خروج البراز بشكل سائل مسبباً فقدان الكثير من السوائل فسوف يعاني الإنسان من الإسهال، ويحتاج إلى محاليل الإماهة (الإرواء) بالفم لتعويض الماء والأملاح. أما إذا تأخر خروج البراز وكان صلباً فسوف يعاني الإنسان من الإمساك، ومن أسبابه: قلة الألياف الغذائية وقلة شرب الماء وقلة الحركة."},{"type":"callout","tone":"warn","title":"النظافة الشخصية","text":"تذكّر أن إهمال قواعد النظافة الشخصية بعد قضاء الحاجة يؤدي إلى مخاطر جسيمة (عدوى الجراثيم والطفيليات)."},{"type":"conceptmap","id":"food-path"}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.lesson_sections (lesson_id, slug, title, position, blocks)
select id, 'health', 'مشكلات صحية وأنماط التغذية', 10, $j$[{"type":"h","text":"دراسة حالة: التهاب الزائدة الدودية"},{"type":"p","text":"استيقظ والد عمرو على صراخ ابنه من شدة الألم في بطنه، فحمله مسرعاً إلى الطبيب. حدّد عمرو أن الألم في الجانب الأيمن من أسفل البطن، وصاح عمرو بشدة حين ضغط الطبيب على موضع الألم ثم رفع يده بسرعة. تبيّن للطبيب أن الأعراض تشير إلى احتمال التهاب في بروز بحجم الخنصر بين الأمعاء الدقيقة والغليظة (الزائدة الدودية)، فأوصى بنقل الطفل بسرعة إلى المشفى للاستئصال الجراحي."},{"type":"callout","tone":"tip","title":"لاحظ","text":"الأعراض التي شعر بها عمرو: ألم شديد في أسفل الجهة اليمنى من البطن يزداد بالضغط. والجزء المصاب هو الزائدة الدودية (انظر الشكل 9)."},{"type":"h","text":"أنماط التغذية عند بعض الكائنات الحية"},{"type":"table","headers":["الكائن","نمط التغذية"],"rows":[["الأميبا","تقوم بالهضم داخل الخلية"],["الدودة الشريطية","لا تمتلك جهازاً هضمياً؛ تتطفّل وتمتص غذاءها عبر جسمها"],["الفراشة","تحوّر الفم إلى أنبوب مجوّف يستطيل عند ضخّ الرحيق"],["الأغنام","جهازها الهضمي متخصص للتغذي على النباتات وهضم السيليلوز"]]},{"type":"sim","id":"food-journey","label":"أعد مشاهدة رحلة الطعام كاملة"}]$j$::jsonb from public.lessons where slug = 'digestive-system'
on conflict (lesson_id, slug) do update set title = excluded.title, position = excluded.position, blocks = excluded.blocks;

insert into public.quizzes (lesson_id, slug, title, description)
select id, 'nutrients-quiz', 'اختبار درس المغذيات', 'اختبار شامل على المغذيات والهرم الغذائي وطرق الكشف.' from public.lessons where slug = 'nutrients'
on conflict (slug) do update set title = excluded.title, description = excluded.description;

do $seed$
declare qid uuid;
begin
  select id into qid from public.quizzes where slug = 'nutrients-quiz';
  if not exists (select 1 from public.quiz_questions where quiz_id = qid) then
    insert into public.quiz_questions (quiz_id, kind, prompt, options, answer_key, explanation, points, position)
    select qid, v.* from (values
  ('mcq'::public.question_kind, 'أي مما يأتي سكر أحادي؟', $j$["المالتوز","السكروز","الفركتوز","النشا"]$j$::jsonb, $j${"value":2}$j$::jsonb, 'الغلوكوز والفركتوز والغالاكتوز سكريات أحادية، أما المالتوز والسكروز فثنائية والنشا متعدد.', 1, 1),
  ('mcq'::public.question_kind, 'الوحدات البنائية للبروتين هي:', $j$["الحموض الدهنية","الحموض الأمينية","السكريات الأحادية","الغليسرول"]$j$::jsonb, $j${"value":1}$j$::jsonb, 'تتكوّن البروتينات من وحدات بنائية تُسمّى الحموض الأمينية.', 1, 2),
  ('mcq'::public.question_kind, 'يُستخدم محلول بندكت للكشف عن:', $j$["البروتينات","الدهون","السكريات المختزلة كالغلوكوز","فيتامين C"]$j$::jsonb, $j${"value":2}$j$::jsonb, 'يعطي بندكت راسباً برتقالياً/أحمر طوبياً مع السكريات المختزلة عند التسخين.', 1, 3),
  ('mcq'::public.question_kind, 'يظهر اللون البنفسجي عند إضافة هيدروكسيد الصوديوم وكبريتات النحاس إلى:', $j$["النشا","زلال البيض","زيت الزيتون","الماء"]$j$::jsonb, $j${"value":1}$j$::jsonb, 'هذا كشف البروتينات.', 1, 4),
  ('mcq'::public.question_kind, 'أي المجموعات الغذائية توجد في قمة الهرم الغذائي؟', $j$["الحبوب","الخضار","الدهون والزيوت والحلويات","الفواكه"]$j$::jsonb, $j${"value":2}$j$::jsonb, 'قمة الهرم لما يُؤخذ بكمية قليلة: الدهون والزيوت والحلويات.', 1, 5),
  ('mcq'::public.question_kind, 'نقص فيتامين D يسبب:', $j$["نزيف اللثة","الأنيميا","الكساح عند الصغار","الإمساك"]$j$::jsonb, $j${"value":2}$j$::jsonb, 'فيتامين D يساعد في امتصاص الكالسيوم، ونقصه يسبب الكساح عند الصغار ولين العظام عند الكبار.', 1, 6),
  ('mcq'::public.question_kind, 'يدخل الحديد في تركيب:', $j$["الهيموغلوبين","السيليلوز","الإنسولين","الإيثانول"]$j$::jsonb, $j${"value":0}$j$::jsonb, 'الحديد ضروري لصناعة خلايا الدم الحمراء (الهيموغلوبين) ونقصه يسبب الأنيميا.', 1, 7),
  ('mcq'::public.question_kind, 'تشكّل نسبة الماء في جسم الإنسان تقريباً:', $j$["20%","40%","70%","95%"]$j$::jsonb, $j${"value":2}$j$::jsonb, 'يشكّل الماء نحو 70% من كتلة الجسم.', 1, 8),
  ('mcq'::public.question_kind, 'الكاشف المستخدم للكشف عن فيتامين C هو:', $j$["اليود","الإندوفينول","الإيثانول","بندكت"]$j$::jsonb, $j${"value":1}$j$::jsonb, 'يزول لون الإندوفينول عند إضافة مصدر غني بفيتامين C.', 1, 9),
  ('true_false'::public.question_kind, 'السيليلوز يُهضم داخل القناة الهضمية للإنسان.', null, $j${"value":false}$j$::jsonb, 'السيليلوز (من الألياف الغذائية) لا يُهضم عند الإنسان لكنه يساعد على دفع الفضلات.', 1, 10),
  ('true_false'::public.question_kind, 'يمكن للجسم تصنيع جميع الحموض الأمينية.', null, $j${"value":false}$j$::jsonb, 'بعض الحموض الأمينية لا تستطيع الخلايا تصنيعها ولا بد من توافرها في الغذاء.', 1, 11),
  ('true_false'::public.question_kind, 'اللاكتوز سكر ثنائي يتكوّن من غلوكوز + غالاكتوز.', null, $j${"value":true}$j$::jsonb, 'اللاكتوز هو سكر الحليب.', 1, 12),
  ('true_false'::public.question_kind, 'تذوب الدهون والزيوت في الماء.', null, $j${"value":false}$j$::jsonb, 'تذوب في الإيثانول ولا تذوب في الماء؛ فالماء قطبي والدهون غير قطبية.', 1, 13),
  ('fill_blank'::public.question_kind, 'من الأمثلة على الكربوهيدرات الثنائية: ___ و ___ و ___ .', null, $j${"values":[["المالتوز"],["السكروز"],["اللاكتوز"]]}$j$::jsonb, 'السكريات الثنائية: المالتوز والسكروز واللاكتوز.', 1, 14),
  ('fill_blank'::public.question_kind, 'الوحدات البنائية للدهون هي حموض ___ و ___ .', null, $j${"values":[["دهنية"],["غليسرول","جلسرول"]]}$j$::jsonb, 'تتكوّن الدهون من حموض دهنية وغليسرول.', 1, 15),
